package com.smarttask.service;
import com.smarttask.dto.ApiDtos.*; import com.smarttask.entity.*; import com.smarttask.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TaskService {private final TaskRepository tasks;private final UserRepository users;public TaskService(TaskRepository t,UserRepository u){tasks=t;users=u;}public List<TaskView> list(Long uid,String q,String status,String sort){var all=tasks.findByUserIdOrderByCreatedAtDesc(uid).stream().filter(t->q==null||q.isBlank()||t.getTitle().toLowerCase().contains(q.toLowerCase())||t.getTags().toLowerCase().contains(q.toLowerCase())).filter(t->status==null||status.isBlank()||t.getStatus().name().equalsIgnoreCase(status)).toList();var res=new ArrayList<>(all);if("dueDate".equals(sort))res.sort(Comparator.comparing(Task::getDueDate,Comparator.nullsLast(Comparator.naturalOrder())));if("priority".equals(sort))res.sort(Comparator.comparing(Task::getPriority).reversed());return res.stream().map(TaskView::of).toList();}@Transactional public TaskView create(Long uid,TaskRequest r){var u=users.findById(uid).orElseThrow();Task parent=r.parentId()==null?null:owned(r.parentId(),uid);return TaskView.of(tasks.save(new Task(u,r.title().trim(),r.description(),value(r.priority(),Task.Priority.MEDIUM),r.dueDate(),r.estimateMinutes(),Boolean.TRUE.equals(r.important()),Boolean.TRUE.equals(r.urgent()),r.tags(),value(r.recurrence(),Task.Recurrence.NONE),parent)));}@Transactional public TaskView update(Long uid,Long id,TaskRequest r){Task t=owned(id,uid);Task parent=r.parentId()==null?null:owned(r.parentId(),uid);if(parent!=null&&parent.getId().equals(id))throw new IllegalArgumentException("A task cannot be its own parent.");t.update(r.title().trim(),r.description(),value(r.status(),t.getStatus()),value(r.priority(),Task.Priority.MEDIUM),r.dueDate(),r.estimateMinutes(),Boolean.TRUE.equals(r.important()),Boolean.TRUE.equals(r.urgent()),r.tags(),value(r.recurrence(),Task.Recurrence.NONE),parent);return TaskView.of(t);}@Transactional public TaskView status(Long uid,Long id,Task.Status status){Task t=owned(id,uid);boolean newlyDone=status==Task.Status.DONE&&t.getStatus()!=Task.Status.DONE;t.setStatus(status);if(newlyDone&&t.getRecurrence()!=Task.Recurrence.NONE){java.time.LocalDate base=t.getDueDate()==null?java.time.LocalDate.now(java.time.ZoneOffset.UTC):t.getDueDate();java.time.LocalDate next=switch(t.getRecurrence()){case DAILY->base.plusDays(1);case WEEKLY->base.plusWeeks(1);case MONTHLY->base.plusMonths(1);default->base;};tasks.save(new Task(t.getUser(),t.getTitle(),t.getDescription(),t.getPriority(),next,t.getEstimateMinutes(),t.getImportant(),t.getUrgent(),t.getTags(),t.getRecurrence(),t.getParent()));}return TaskView.of(t);}@Transactional public void delete(Long uid,Long id){tasks.delete(owned(id,uid));}public List<Task> raw(Long uid){return tasks.findByUserIdOrderByCreatedAtDesc(uid);}private Task owned(Long id,Long uid){return tasks.findByIdAndUserId(id,uid).orElseThrow(()->new NoSuchElementException("Task not found."));}private <T>T value(T a,T b){return a==null?b:a;}}
